import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

/* ── Helpers ── */
function StatutBadge({ statut }) {
  const cfg = {
    en_attente: { bg: 'rgba(245,158,11,0.12)', color: '#f59e0b', dot: '#f59e0b', label: 'En attente'  },
    confirmé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', dot: '#43e97b', label: 'Confirmé'    },
    refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', dot: '#ff6584', label: 'Refusé'      },
    annulé:     { bg: 'rgba(153,153,187,0.12)', color: '#9999bb', dot: '#9999bb', label: 'Annulé'      },
    terminé:    { bg: 'rgba(56,189,248,0.12)',  color: '#38bdf8', dot: '#38bdf8', label: 'Terminé'     },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', dot: 'var(--text2)', label: statut };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: '.72rem', fontWeight: 700, padding: '4px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: cfg.dot }} />
      {cfg.label}
    </span>
  );
}

function ModeBadge({ mode }) {
  if (mode === 'en_ligne') return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: 'rgba(56,189,248,0.1)', color: '#38bdf8' }}>
      🌐 En ligne
    </span>
  );
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: 'rgba(67,233,123,0.1)', color: '#43e97b' }}>
      🏫 Présentiel
    </span>
  );
}

function Avatar({ nom, prenom, photo, size = 40 }) {
  const initials = `${(prenom || '')[0] || ''}${(nom || '')[0] || ''}`.toUpperCase();
  return (
    <div style={{ width: size, height: size, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: size * 0.35, fontWeight: 700, color: '#fff', overflow: 'hidden', flexShrink: 0 }}>
      {photo
        ? <img src={`http://localhost:8001${photo}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        : initials || '👨‍🎓'}
    </div>
  );
}

/* ════════════════════════════════════════════════
   MODAL DÉTAIL RÉSERVATION
════════════════════════════════════════════════ */
function ReservationModal({ reservation, onClose, onAction }) {
  if (!reservation) return null;
  const r = reservation;

  return (
    <div
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.75)', backdropFilter: 'blur(6px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}
    >
      <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 24, width: '100%', maxWidth: 560, maxHeight: '90vh', overflowY: 'auto', padding: 0, animation: 'modalIn .25s ease', boxShadow: '0 24px 80px rgba(0,0,0,0.5)' }}>
        <style>{`@keyframes modalIn{from{opacity:0;transform:scale(.95)}to{opacity:1;transform:scale(1)}}`}</style>

        {/* Header */}
        <div style={{ padding: '24px 28px 20px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1.1rem' }}>📋 Détails de la réservation</h3>
            <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginTop: 4 }}>Réservation #{r.id}</div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <StatutBadge statut={r.statut} />
            <button onClick={onClose} style={{ width: 32, height: 32, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
          </div>
        </div>

        <div style={{ padding: 28 }}>

          {/* Profil étudiant */}
          <div style={{ background: 'linear-gradient(135deg,rgba(108,99,255,0.08),rgba(255,101,132,0.05))', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 16, padding: 20, marginBottom: 20 }}>
            <div style={{ fontSize: '.7rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', marginBottom: 14 }}>👨‍🎓 Étudiant</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
              <Avatar nom={r.etudiant_nom?.split(' ')[1]} prenom={r.etudiant_nom?.split(' ')[0]} size={52} />
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '1.05rem', marginBottom: 6 }}>{r.etudiant_nom || '—'}</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                  {r.etudiant_email && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.8rem', color: 'var(--text2)' }}>
                      <span>✉️</span>
                      <a href={`mailto:${r.etudiant_email}`} style={{ color: '#6c63ff', textDecoration: 'none' }}>{r.etudiant_email}</a>
                    </div>
                  )}
                  {r.etudiant_telephone && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.8rem', color: 'var(--text2)' }}>
                      <span>📞</span>
                      <a href={`tel:${r.etudiant_telephone}`} style={{ color: '#6c63ff', textDecoration: 'none' }}>{r.etudiant_telephone}</a>
                    </div>
                  )}
                  {r.etudiant_niveau && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.8rem', color: 'var(--text2)' }}>
                      <span>🎓</span> {r.etudiant_niveau}
                    </div>
                  )}
                  {r.etudiant_ville && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.8rem', color: 'var(--text2)' }}>
                      <span>📍</span> {r.etudiant_ville}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Détails cours */}
          <div style={{ background: 'var(--surface2)', borderRadius: 14, padding: 18, marginBottom: 16 }}>
            <div style={{ fontSize: '.7rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', marginBottom: 14 }}>📚 Détails du cours</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              {[
                ['📅 Date',       r.date_cours ? new Date(r.date_cours + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '—'],
                ['🕒 Horaire',    r.heure_debut && r.heure_fin ? `${String(r.heure_debut).slice(0,5)} → ${String(r.heure_fin).slice(0,5)}` : '—'],
                ['🎓 Mode',       null],
                ['💰 Tarif',      r.tarif_applique ? `${r.tarif_applique} DT/h` : 'Non renseigné'],
              ].map(([label, value]) => (
                <div key={label} style={{ background: 'var(--card)', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)' }}>
                  <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginBottom: 4 }}>{label}</div>
                  {label === '🎓 Mode'
                    ? <ModeBadge mode={r.mode_seance} />
                    : <div style={{ fontWeight: 700, fontSize: '.88rem' }}>{value}</div>}
                </div>
              ))}
            </div>
          </div>

          {/* Lien Meet si en ligne */}
          {r.mode_seance === 'en_ligne' && r.lien_meet && (
            <div style={{ background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.25)', borderRadius: 12, padding: 14, marginBottom: 16 }}>
              <div style={{ fontWeight: 700, color: '#38bdf8', marginBottom: 8, fontSize: '.85rem' }}>🎥 Lien Google Meet</div>
              <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, background: 'linear-gradient(135deg,#38bdf8,#0ea5e9)', color: '#fff', padding: '10px', borderRadius: 10, fontWeight: 700, textDecoration: 'none', fontSize: '.85rem' }}>
                📹 Rejoindre le Meet
              </a>
            </div>
          )}

          {/* Message de l'étudiant */}
          {r.notes_etudiant && (
            <div style={{ background: 'var(--surface2)', borderRadius: 14, padding: 16, marginBottom: 20, border: '1px solid var(--border)' }}>
              <div style={{ fontSize: '.7rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', marginBottom: 10 }}>💬 Message de l'étudiant</div>
              <div style={{ fontSize: '.88rem', color: 'var(--text)', lineHeight: 1.7, fontStyle: 'italic', padding: '12px 14px', background: 'var(--card)', borderRadius: 10, borderLeft: '3px solid #6c63ff' }}>
                "{r.notes_etudiant}"
              </div>
            </div>
          )}

          {/* Actions */}
          {r.statut === 'en_attente' && (
            <div style={{ display: 'flex', gap: 12 }}>
              <button
                onClick={() => { onAction(r.id, 'confirmé'); onClose(); }}
                style={{ flex: 1, padding: '13px', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', color: '#000', border: 'none', borderRadius: 12, fontWeight: 700, cursor: 'pointer', fontSize: '.9rem' }}
              >
                ✅ Accepter la réservation
              </button>
              <button
                onClick={() => { onAction(r.id, 'refusé'); onClose(); }}
                style={{ flex: 1, padding: '13px', background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.3)', borderRadius: 12, fontWeight: 700, cursor: 'pointer', fontSize: '.9rem' }}
              >
                ❌ Refuser
              </button>
            </div>
          )}

          {r.statut !== 'en_attente' && (
            <div style={{ textAlign: 'center', padding: '12px', background: 'var(--surface2)', borderRadius: 10, fontSize: '.85rem', color: 'var(--text2)' }}>
              Cette réservation a déjà été traitée · <StatutBadge statut={r.statut} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   CARTE RÉSERVATION COMPACTE
════════════════════════════════════════════════ */
function ReservationCard({ r, onView, onAction }) {
  const [hovered, setHovered] = useState(false);

  const dateStr = r.date_cours
    ? new Date(r.date_cours + 'T00:00:00').toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', year: 'numeric' })
    : '—';

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: 'var(--surface2)', border: hovered ? '1px solid rgba(108,99,255,0.4)' : '1px solid var(--border)',
        borderRadius: 16, padding: '16px 18px', transition: 'all .2s',
        boxShadow: hovered ? '0 4px 20px rgba(108,99,255,0.1)' : 'none',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>

        {/* Avatar étudiant */}
        <Avatar
          nom={r.etudiant_nom?.split(' ')[1]}
          prenom={r.etudiant_nom?.split(' ')[0]}
          size={44}
        />

        {/* Infos principales */}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4, flexWrap: 'wrap' }}>
            <span style={{ fontWeight: 700, fontSize: '.92rem' }}>{r.etudiant_nom || 'Étudiant'}</span>
            <StatutBadge statut={r.statut} />
            <ModeBadge mode={r.mode_seance} />
          </div>
          <div style={{ display: 'flex', gap: 12, fontSize: '.78rem', color: 'var(--text2)', flexWrap: 'wrap' }}>
            <span>📅 {dateStr}</span>
            <span>🕒 {String(r.heure_debut || '').slice(0,5)} – {String(r.heure_fin || '').slice(0,5)}</span>
            {r.tarif_applique && <span style={{ color: '#43e97b', fontWeight: 600 }}>💰 {r.tarif_applique} DT/h</span>}
          </div>
          {/* Aperçu message */}
          {r.notes_etudiant && (
            <div style={{ marginTop: 6, fontSize: '.76rem', color: 'var(--text2)', fontStyle: 'italic', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 300 }}>
              💬 "{r.notes_etudiant}"
            </div>
          )}
        </div>

        {/* Actions */}
        <div style={{ display: 'flex', gap: 8, flexShrink: 0 }}>
          <button
            onClick={() => onView(r)}
            style={{ padding: '7px 12px', background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 8, cursor: 'pointer', color: 'var(--text)', fontSize: '.78rem', fontWeight: 600 }}
          >
            👁 Détails
          </button>
          {r.statut === 'en_attente' && (
            <>
              <button
                onClick={() => onAction(r.id, 'confirmé')}
                style={{ padding: '7px 12px', background: 'rgba(67,233,123,0.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,0.3)', borderRadius: 8, cursor: 'pointer', fontSize: '.78rem', fontWeight: 700 }}
              >
                ✅
              </button>
              <button
                onClick={() => onAction(r.id, 'refusé')}
                style={{ padding: '7px 12px', background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 8, cursor: 'pointer', fontSize: '.78rem', fontWeight: 700 }}
              >
                ❌
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   PAGE PRINCIPALE — TABLEAU DE BORD PROF
════════════════════════════════════════════════ */
export default function ProfDashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [reservations, setReservations] = useState([]);
  const [profile, setProfile]           = useState(null);
  const [loading, setLoading]           = useState(true);
  const [loadingError, setLoadingError] = useState(false);
  const [selectedResa, setSelectedResa] = useState(null);
  const [activeTab, setActiveTab]       = useState('en_attente');

  useEffect(() => {
    Promise.all([
      api.get('/api/reservations/mes-reservations').catch(() => ({ data: [] })),
      api.get('/api/professeurs/me').catch(() => ({ data: null })),
    ]).then(([resResa, resProfile]) => {
      setReservations(resResa.data ?? []);
      setProfile(resProfile.data ?? null);
      setLoading(false);
    }).catch(() => {
      setLoadingError(true);
      setLoading(false);
    });
  }, []);

  async function updateReservation(id, statut) {
    try {
      await api.put(`/api/reservations/${id}`, { statut });
      setReservations(prev => prev.map(r => r.id === id ? { ...r, statut } : r));
    } catch (e) {
      alert('Erreur lors de la mise à jour');
    }
  }

  const tabs = [
    { key: 'en_attente', label: 'En attente',  color: '#f59e0b' },
    { key: 'confirmé',   label: 'Confirmées',  color: '#43e97b' },
    { key: 'refusé',     label: 'Refusées',    color: '#ff6584' },
    { key: 'all',        label: 'Toutes',      color: '#6c63ff' },
  ];

  const filtered = activeTab === 'all'
    ? reservations
    : reservations.filter(r => r.statut === activeTab);

  const counts = {
    en_attente: reservations.filter(r => r.statut === 'en_attente').length,
    confirmé:   reservations.filter(r => r.statut === 'confirmé').length,
    refusé:     reservations.filter(r => r.statut === 'refusé').length,
    all:        reservations.length,
  };

  const statCards = [
    { icon: '📅', val: reservations.length,                                    lbl: 'Réservations totales', color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
    { icon: '⏳', val: counts.en_attente,                                       lbl: 'En attente',           color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
    { icon: '✅', val: counts.confirmé,                                          lbl: 'Confirmées',           color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
    { icon: '⭐', val: parseFloat(profile?.note_moyenne || 0).toFixed(1),       lbl: 'Note moyenne',         color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
  ];

  if (loadingError) return (
    <div style={{ padding: 32, textAlign: 'center', color: 'var(--text2)' }}>
      Une erreur est survenue. Veuillez rafraîchir la page.
    </div>
  );

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* ── HEADER ── */}
      <div style={{ marginBottom: 28 }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.6rem', marginBottom: 4 }}>
          Bonjour, {user?.prenom} 👨‍🏫
        </div>
        <div style={{ color: 'var(--text2)', fontSize: '.9rem' }}>
          Voici un aperçu de votre activité réelle
        </div>
      </div>

      {/* ── STAT CARDS ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 20, marginBottom: 32 }}>
        {statCards.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 20, display: 'flex', alignItems: 'center', gap: 16 }}>
            <div style={{ width: 48, height: 48, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.3rem', flexShrink: 0 }}>
              {s.icon}
            </div>
            <div>
              <div style={{ fontFamily: 'Syne', fontSize: '1.7rem', fontWeight: 800, color: s.color, lineHeight: 1 }}>{s.val}</div>
              <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 3 }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ── ALERTE EN ATTENTE ── */}
      {counts.en_attente > 0 && (
        <div style={{ marginBottom: 24, padding: '14px 20px', background: 'rgba(245,158,11,0.07)', border: '1px solid rgba(245,158,11,0.25)', borderRadius: 14, display: 'flex', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: '1.3rem' }}>🔔</span>
          <div>
            <div style={{ fontWeight: 700, color: '#f59e0b', fontSize: '.9rem' }}>
              {counts.en_attente} demande{counts.en_attente > 1 ? 's' : ''} de réservation en attente de votre réponse
            </div>
            <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 2 }}>
              Répondez rapidement pour ne pas faire attendre vos étudiants.
            </div>
          </div>
          <button
            onClick={() => setActiveTab('en_attente')}
            style={{ marginLeft: 'auto', padding: '7px 14px', background: 'rgba(245,158,11,0.2)', color: '#f59e0b', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 9, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem', whiteSpace: 'nowrap' }}
          >
            Voir →
          </button>
        </div>
      )}

      {/* ── SECTION RÉSERVATIONS ── */}
      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 28 }}>

        {/* Header section */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <div>
            <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1.1rem' }}>📩 Demandes de réservation</h3>
            <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 3 }}>
              Gérez les demandes de vos étudiants
            </div>
          </div>
        </div>

        {/* Onglets filtre */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 20, borderBottom: '1px solid var(--border)', paddingBottom: 16 }}>
          {tabs.map(t => (
            <button
              key={t.key}
              onClick={() => setActiveTab(t.key)}
              style={{
                padding: '7px 14px', borderRadius: 20, cursor: 'pointer',
                fontWeight: 600, fontSize: '.8rem', transition: 'all .2s',
                border: activeTab === t.key ? `1px solid ${t.color}` : '1px solid var(--border)',
                background: activeTab === t.key ? `${t.color}20` : 'var(--surface2)',
                color: activeTab === t.key ? t.color : 'var(--text2)',
                display: 'flex', alignItems: 'center', gap: 6,
              }}
            >
              {t.label}
              <span style={{
                background: activeTab === t.key ? t.color : 'var(--border)',
                color: activeTab === t.key ? '#000' : 'var(--text2)',
                fontSize: '.65rem', fontWeight: 800,
                padding: '1px 6px', borderRadius: 20, minWidth: 18, textAlign: 'center',
              }}>
                {counts[t.key]}
              </span>
            </button>
          ))}
        </div>

        {/* Liste des réservations */}
        {loading ? (
          <div style={{ padding: 40, textAlign: 'center', color: 'var(--text2)' }}>⏳ Chargement...</div>
        ) : filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '50px 20px', color: 'var(--text2)' }}>
            <div style={{ fontSize: '2.5rem', marginBottom: 12 }}>
              {activeTab === 'en_attente' ? '✅' : activeTab === 'confirmé' ? '📅' : '📭'}
            </div>
            <div style={{ fontWeight: 600, marginBottom: 4 }}>
              {activeTab === 'en_attente' ? 'Aucune demande en attente' :
               activeTab === 'confirmé'   ? 'Aucune réservation confirmée' :
               activeTab === 'refusé'     ? 'Aucune réservation refusée' :
               'Aucune réservation'}
            </div>
            <div style={{ fontSize: '.82rem' }}>
              {activeTab === 'en_attente' ? 'Super ! Vous avez traité toutes les demandes.' : 'Les réservations apparaîtront ici.'}
            </div>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {filtered
              .sort((a, b) => {
                // En attente en premier
                if (a.statut === 'en_attente' && b.statut !== 'en_attente') return -1;
                if (b.statut === 'en_attente' && a.statut !== 'en_attente') return 1;
                return new Date(b.created_at || 0) - new Date(a.created_at || 0);
              })
              .map(r => (
                <ReservationCard
                  key={r.id}
                  r={r}
                  onView={setSelectedResa}
                  onAction={updateReservation}
                />
              ))}
          </div>
        )}
      </div>

      {/* ── MODAL DÉTAIL ── */}
      {selectedResa && (
        <ReservationModal
          reservation={selectedResa}
          onClose={() => setSelectedResa(null)}
          onAction={(id, statut) => {
            updateReservation(id, statut);
            setSelectedResa(prev => prev ? { ...prev, statut } : null);
          }}
        />
      )}
    </div>
  );
}
